/** Разбор строки в точки: [x, y, вес 0..1]. */
export function parsePoints(packed) {
  const n = packed.split(",");
  const out = [];
  for (let i = 0; i < n.length; i += 3) {
    out.push([Number(n[i]), Number(n[i + 1]), Number(n[i + 2]) / 15]);
  }
  return out;
}